#include "../../05-数学/线性规划单纯形.cpp"
int main(){using R=long double;vector<R>x;assert(isinf(LPSolver({{-1},{1}},{-2,1},{1}).Solve(x)));assert(LPSolver({{-1}},{-1},{1}).Solve(x)>1e100);assert(fabsl(LPSolver({{1,0},{0,1},{1,1}},{2,3,4},{3,2}).Solve(x)-10)<1e-8);assert(LPSolver({}, {}, {-1}).Solve(x)==0);assert(LPSolver({{}},{-1},{}).Solve(x)<-1e100);mt19937 r(127);for(int t=0;t<300;t++){vector<vector<R>> a={{1,0},{0,1},{-1,0},{0,-1}};vector<R>b={10,10,0,0},c={R(int(r()%21)-10),R(int(r()%21)-10)};for(int i=0;i<5;i++)a.push_back({R(r()%8),R(r()%8)}),b.push_back(1+r()%40);R want=-1e100;for(int i=0;i<(int)a.size();i++)for(int j=0;j<i;j++){R det=a[i][0]*a[j][1]-a[i][1]*a[j][0];if(fabsl(det)<1e-12)continue;R X=(b[i]*a[j][1]-a[i][1]*b[j])/det,Y=(a[i][0]*b[j]-b[i]*a[j][0])/det;bool ok=true;for(int k=0;k<(int)a.size();k++)if(a[k][0]*X+a[k][1]*Y>b[k]+1e-8)ok=false;if(ok)want=max(want,c[0]*X+c[1]*Y);}R ans=LPSolver(a,b,c).Solve(x);assert(fabsl(ans-want)<1e-7);}}
